import { z } from 'zod';
import { hashSchema } from '../contracts/content';
import { driveIdSchema } from './drive';

/** content/<section>/<driveId>.json next to the unchanged <driveId>.pdf. Generated by sync only. */
export const documentMetaSchema = z.strictObject({
  id: driveIdSchema, title: z.string().min(1).max(300),
  updatedAt: z.iso.datetime(), sizeBytes: z.number().int().positive(), sha256: hashSchema,
});
export type DocumentMeta = z.infer<typeof documentMetaSchema>;
export const MAX_PDF_BYTES = 20 * 1024 * 1024;
export const serializeMeta = (meta: DocumentMeta) => JSON.stringify(documentMetaSchema.parse(meta), null, 2) + '\n';
